:root {
  --paper: #fffdf5;
  --ink: #183b3a;
  --mint: #d9f1df;
  --line: #9bc8b5;
}

.receipt {
  width: 440px;
  box-sizing: border-box;
  padding: 18px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.receipt-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.recycle-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--mint);
  font-size: 24px;
}

.eyebrow {
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
}

.receipt-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin: 16px 0 12px;
  padding: 12px 0;
  border-top: 1px dashed var(--line);
  border-bottom: 1px dashed var(--line);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.receipt-total strong {
  font-size: 27px;
  letter-spacing: 0;
}

.receipt-total small {
  font-size: 13px;
}

.receipt-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.receipt-footer b {
  color: var(--ink);
}
